-- Payroll module (payroll.db)
-- Monthly salary runs and their payment state.
-- Generated by Migrations/build_module_databases.py --refresh-schema;
-- foreign keys into another module's file are dropped on purpose.

CREATE TABLE payroll (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                employee_id INTEGER NOT NULL,
                payroll_month TEXT NOT NULL,
                basic_salary REAL NOT NULL CHECK (basic_salary >= 0),
                allowances REAL NOT NULL DEFAULT 0 CHECK (allowances >= 0),
                deductions REAL NOT NULL DEFAULT 0 CHECK (deductions >= 0),
                net_salary REAL NOT NULL CHECK (net_salary >= 0),
                payment_status TEXT NOT NULL DEFAULT 'Pending'
                    CHECK (payment_status IN ('Pending', 'Paid')),
                notes TEXT DEFAULT '',
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                UNIQUE (employee_id, payroll_month)
            );

CREATE INDEX idx_payroll_employee
                ON payroll(employee_id, payroll_month);
CREATE INDEX idx_payroll_month
                ON payroll(payroll_month);
CREATE INDEX idx_payroll_status
                ON payroll(payment_status);
